// evaluate: a dome of radius 10 (a quarter disc revolved about z): its spherical face's directions
export function c003(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 10) * millimeter, "end" : vector(0, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skArc(s1, "a1", { "start" : vector(10, 0) * millimeter, "mid" : vector(7.071068, 7.071068) * millimeter, "end" : vector(0, 10) * millimeter });
    skSolve(s1);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : sketchEntityQuery(id + "s1", EntityType.EDGE, "l1"), "fullRevolve" : true });
    return { "directions" : directions(context, qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.SPHERE), [vector(0, 0.2), vector(0, 0.5), vector(0, 0.75), vector(0.1, 0.2), vector(0.1, 0.5), vector(0.1, 0.75), vector(0.25, 0.2), vector(0.25, 0.5), vector(0.25, 0.75), vector(0.4, 0.2), vector(0.4, 0.5), vector(0.4, 0.75), vector(0.5, 0.2), vector(0.5, 0.5), vector(0.5, 0.75), vector(0.65, 0.2), vector(0.65, 0.5), vector(0.65, 0.75), vector(0.8, 0.2), vector(0.8, 0.5), vector(0.8, 0.75), vector(0.9, 0.2), vector(0.9, 0.5), vector(0.9, 0.75)]) };
}
